export default function build({holeScale=parameters.holeScale,edgeRadius=parameters.edgeRadius}={}){
 if(!Number.isFinite(edgeRadius)||edgeRadius<=0||edgeRadius>=0.75)throw Error('Edge radius must be between 0 and 0.75 mm');
 const shape=unwrap(fuseAll(profiles.map(p=>buildPrismaticPart(p,{holeScale}))));
 const back=profiles[0].origin[1],pocketFloor=profiles[1].origin[1],bearingShoulder=profiles[2].origin[1];
 const edges=getEdges(shape).filter(e=>{const box=getBounds(e);if(box.yMax-box.yMin>1e-5)return false;
  if(Math.abs(box.yMin-bearingShoulder)<1e-5)return false;
  if(Math.abs(box.yMin-back)<1e-5&&getCurveType(e)==='CIRCLE'&&curveIsClosed(e))return false;
  if(Math.abs(box.yMin-pocketFloor)<1e-5&&box.zMin>332)return false;
  return true;
 });
 return unwrap(fillet(shape,edges,edgeRadius));
}
